            note_name_size = get_le32(buf + offset + sizeof(note_type));
            note_desc_size = get_le32(buf + offset + sizeof(note_type) + sizeof(note_name_size));
        }

        note_total_size = sizeof(note_type) + sizeof(note_name_size) + sizeof(note_desc_size) + ((note_name_size + 3) & ~3) + ((note_desc_size + 3) & ~3);

        if (offset + note_total_size > size) {
            break;
        }

        switch (note_type) {
