size_t process_note_headers(struct magic_set *ms, void *vbuf, size_t offset, size_t size, int clazz, int swap, size_t align, int *flags, uint16_t *notecount) {
    uint16_t note_type;
    size_t note_name_size, note_desc_size, note_total_size;
    size_t end = size;
    uint8_t *buf = (uint8_t *)vbuf;

    while (offset < end && *notecount > 0) {
        if (offset + sizeof(note_type) + sizeof(note_name_size) + sizeof(note_desc_size) > end) {
            break;
        }

        if (clazz == MSB || clazz == LSB) {
            if (swap) {
                note_type = le16dec(buf + offset);
            } else {
                note_type = be16dec(buf + offset);
            }
        } else {
            note_type = *(uint16_t *)(buf + offset);
        }

        offset += sizeof(note_type);

        if (clazz == MSB || clazz == LSB) {
            if (swap) {
                note_name_size = le32dec(buf + offset);
                note_desc_size = le32dec(buf + offset + sizeof(note_name_size));
            } else {
                note_name_size = be32dec(buf + offset);
                note_desc_size = be32dec(buf + offset + sizeof(note_name_size));
            }
        } else {
            note_name_size = *(uint32_t *)(buf + offset);
            note_desc_size = *(uint32_t *)(buf + offset + sizeof(note_name_size));
        }

        offset += sizeof(note_name_size) + sizeof(note_desc_size);

        note_total_size = sizeof(note_type) + sizeof(note_name_size) + sizeof(note_desc_size) + ((note_name_size + align - 1) / align) * align + ((note_desc_size + align - 1) / align) * align;

        if (offset + ((note_name_size + align - 1) / align) * align + ((note_desc_size + align - 1) / align) * align > end) {
            break;
        }

        if (note_type == NT_NETBSD) {
            *flags |= NOTE_NETBSD;
        }

        *notecount -= 1;
        offset = (offset + note_total_size);
    }

    if (offset > size) {
        offset = size;
    }

    return offset;
}

size_t process_note_headers(struct magic_set *ms, void *vbuf, size_t offset, size_t size, int clazz, int swap, size_t align, int *flags, uint16_t *notecount) {
    uint8_t *buf = (uint8_t *)vbuf;
    size_t new_offset = offset;

    while (new_offset < size && *notecount > 0) {
        uint32_t note_type;
        uint32_t note_size;

        if (new_offset + sizeof(note_type) + sizeof(note_size) > size) {
            break;
        }

        if (swap) {
            note_type = le32toh(*((uint32_t *)(buf + new_offset)));
            note_size = le32toh(*((uint32_t *)(buf + new_offset + sizeof(note_type))));
        } else {
            note_type = *((uint32_t *)(buf + new_offset));
            note_size = *((uint32_t *)(buf + new_offset + sizeof(note_type)));
        }

        new_offset += sizeof(note_type) + sizeof(note_size);

        if (note_size == 0) {
            break;
        }

        if (new_offset + note_size > size) {
            break;
        }

        if (clazz == EM_NETBSD) {
            if (note_type == NT_NETBSD_CORE) {
                *flags |= NOTE_CORE;
            }
        }

        new_offset += note_size;
        new_offset = (new_offset + align - 1) & ~(align - 1);
        (*notecount)--;
    }

    return new_offset;
}

size_t process_note_headers(struct magic_set *ms, void *vbuf, size_t offset,
                            size_t size, int clazz, int swap, size_t align,
                            int *flags, uint16_t *notecount) {
  uint16_t name_size, desc_size, note_type;
  size_t note_size, new_offset = offset;
  char *buf = (char *)vbuf;

  while (new_offset + align <= size) {
    if (*notecount == 0)
      break;

    if (clazz == MSB || clazz == LSB) {
      if (new_offset + align + 3 > size)
        break;

      if (swap) {
        name_size = (buf[new_offset] << 8) | buf[new_offset + 1];
        desc_size = (buf[new_offset + 2] << 8) | buf[new_offset + 3];
        note_type = (buf[new_offset + 4] << 8) | buf[new_offset + 5];
      } else {
        name_size = (buf[new_offset + 1] << 8) | buf[new_offset];
        desc_size = (buf[new_offset + 3] << 8) | buf[new_offset + 2];
        note_type = (buf[new_offset + 5] << 8) | buf[new_offset + 4];
      }

      note_size = 6 + align + ((name_size + 3) & ~3) + ((desc_size + 3) & ~3);

      if (new_offset + note_size > size)
        break;

      switch (note_type) {
        case NT_NETBSD:
          *flags |= NOTE_NETBSD;
          break;
        default:
          break;
      }

      new_offset += note_size;
      (*notecount)--;
    } else {
      break;
    }
  }

  if (new_offset > size)
    new_offset = size;

  return new_offset;
}

size_t process_note_headers(struct magic_set *ms, void *vbuf, size_t offset, size_t size, int clazz, int swap, size_t align, int *flags, uint16_t *notecount) {
    uint16_t note_type;
    uint32_t note_size;
    size_t new_offset = offset;

    while (new_offset < size && *notecount > 0) {
        /* Ensure we have enough data to read the note header */
        if (new_offset + sizeof(note_type) + sizeof(note_size) > size) {
            break;
        }

        /* Read note type and size (adjusting for endianness if needed) */
        if (swap) {
            note_type = le16toh(*((uint16_t *)((char *)vbuf + new_offset)));
            note_size = le32toh(*((uint32_t *)((char *)vbuf + new_offset + sizeof(note_type))));
        } else {
            note_type = *((uint16_t *)((char *)vbuf + new_offset));
            note_size = *((uint32_t *)((char *)vbuf + new_offset + sizeof(note_type)));
        }

        /* Handle alignment requirements */
        if (note_type == NT_NETBSD_CORE) {
            /* Handle NetBSD-specific note type */
            if (note_size < sizeof(note_type) + sizeof(note_size)) {
                break;
            }

            new_offset += sizeof(note_type) + sizeof(note_size);
            note_size -= sizeof(note_type) + sizeof(note_size);

            if (new_offset + note_size > size) {
                break;
            }

            /* Mark flag if needed */
            if (note_type == NT_PRSTATUS) {
                *flags |= 0x01;
            }
        } else {
            break;
        }

        /* Update offset and note count */
        new_offset += note_size;
        (*notecount)--;
    }

    return new_offset;
}
